-- rares and hunter tames of Classic zones that the retail addon had (with their drops and notes)
local function addRareFull(map, npc, name, items, note, hunter, pts)
    local block = SFP.Rares[map]
    if not block then block = { exp = "classic" }; SFP.Rares[map] = block end
    block[#block + 1] = { npc = npc, name = name, items = items, note = note, hunter = hunter, pts = pts }
end
